public(package) fun handle_withdraw<MarketType, CoinType>(
    self: &mut Market<MarketType>,
    obligation_id: ID,
    ctoken_amount: u64,
    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    now: u64,
    ctx: &mut TxContext,
): (Coin<CoinType>, u64) {
    assert!(ctoken_amount != 0, error::no_zero_amount());

    let name = type_name::with_defining_ids<CoinType>();

    let asset = self.assets.load_by_type(name);
    assert!(!asset.withdraw_paused(), error::withdraw_paused_for_asset());


    let obligation = self.obligations.borrow_mut(obligation_id);
    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());

    // refresh all interest
    let emode_group = self.emode_group_registry.borrow_emode_group_mut(obligation.emode_group());
    refresh_obligation_assets_interest<MarketType>(&self.assets, emode_group, &mut self.reserves, obligation, now);

    let ctoken = obligation.withdraw_ctokens(ctoken_amount);
    let ctokens_left = obligation.ctoken_amount_by_coin(name);

    // TODO: if the asset is not collateral, skip obligation safety check
    let is_obligation_safe = is_obligation_safe(
        self.emode_group_registry.borrow_emode_group(obligation.emode_group()),
        &self.reserves,
        &self.ema_spot_tolerance,

        obligation,
        coin_decimals_registry,
        x_oracle,
        clock,
    );
    assert!(is_obligation_safe, error::obligation_not_safe_after_operation());

    let reserve = self.reserves.load_mut_by_type(name);
    let deposit = reserve.burn_ctokens<MarketType, CoinType>(ctoken.into_coin(ctx));

    // rate limit deposit withdraw
    let emode = self.emode_group_registry.borrow_mut_emode(obligation.emode_group(), type_name::with_defining_ids<CoinType>());
    emode.borrow_mut_deposit_limiter().add_outflow(
        now,
        deposit.value(),
    );

    // update adl

    // use ceiling, slighly more 
    let total_deposit = reserve.total_deposit_plus_interest().ceil();
    let adl = dynamic_field::borrow_mut<ADLRegistryKey, AutoDeleverageRegistry>(&mut self.id, ADLRegistryKey {});
    adl.try_stop_collateral_deleverage<CoinType>(type_name::with_defining_ids<MarketType>(), total_deposit);



    (deposit.into_coin(ctx), ctokens_left)
}

public(package) fun handle_borrow<MarketType, CoinType>(
    self: &mut Market<MarketType>,
    obligation_id: ID,
    borrow_amount: u64,
    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    now: u64,
): (Balance<CoinType>, Decimal, Decimal) {
    assert!(borrow_amount != 0, error::no_zero_amount());

    let name = type_name::with_defining_ids<CoinType>();



    // basic checks
    let asset = self.assets.load_mut_by_type(name);
    assert!(!asset.borrow_paused(), error::borrow_paused_for_asset());



    // load data for later checks
    let asset_config = asset.asset_config();
    let min_borrow_amount = asset_config.min_borrow_amount();
    let asset_max_borrow_amount = asset_config.max_borrow_amount();


    let obligation = self
        .obligations
        .borrow_mut(obligation_id);
    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());
    let asset_name = type_name::with_defining_ids<CoinType>();

    // make sure the outflow is rate limited
    let emode = self.emode_group_registry.borrow_mut_emode(obligation.emode_group(), asset_name);
    let emode_max_borrow_amount = emode.borrow().max_borrow_amount();
    emode.borrow_mut_borrow_limiter().add_outflow(now, borrow_amount);

    let obligation_old_total_borrow_amount = if (!obligation.has_debt(name)) { float::zero() } else { obligation.debt(name).unsafe_debt_amount() };

    // refresh only borrow, practically, obligation owner can borrow a bit more due to collateral interest
    refresh_obligation_borrow_interest_with_new_borrow<MarketType>(name, &self.assets, &mut self.reserves, obligation, now);

    // update obligation
    let borrow_index = self.reserves.load_by_type(name).borrow_index().value();

    obligation.try_borrow_asset<MarketType, CoinType>(borrow_amount, borrow_index);
    obligation.enforce_post_borrow_repay_invariant<MarketType, CoinType>(min_borrow_amount);

    // interest updated, should be up to date
    let obligation_new_total_borrow_amount = obligation.debt(name).unsafe_debt_amount();
    let emode_group = self.emode_group_registry.borrow_emode_group_mut(obligation.emode_group());


    // make sure the emode group borrow limit is not breached
    let emode_group_total_borrow = emode_group.update_asset_borrow(name, obligation_old_total_borrow_amount, obligation_new_total_borrow_amount);
    assert!(emode_group_total_borrow.le(math::float::from(emode_max_borrow_amount)), error::emode_borrow_limit_exceeded());

    let is_obligation_safe = is_obligation_safe(
        emode_group,
        &self.reserves,
        &self.ema_spot_tolerance,

        self.obligations.borrow(obligation_id),
        coin_decimals_registry,
        x_oracle,
        clock,
    );
    assert!(is_obligation_safe, error::obligation_not_safe_after_operation());

    // perform borrow
    let reserve = self.reserves.load_mut_by_type(name);
    let balance = reserve.borrow_amount<MarketType, CoinType>(borrow_amount);

    assert!((*reserve.debt()).ceil() <= asset_max_borrow_amount, error::market_borrow_limit_exceeded());

    (balance, borrow_index, obligation_new_total_borrow_amount)
}

public(package) fun handle_repay<MarketType, CoinType>(
    self: &mut Market<MarketType>,
    obligation_id: ID,
    mut coin: Coin<CoinType>,
    now: u64,
    ctx: &mut TxContext,
): (Coin<CoinType>, Decimal, Decimal) {
    assert!(coin.value() != 0, error::no_zero_amount());

    let name = type_name::with_defining_ids<CoinType>();

    let asset = self.assets.load_mut_by_type(name);
    let min_borrow_amount = asset.asset_config().min_borrow_amount();

    let reserve = accrue_interest<MarketType>(name, &mut self.reserves, asset.asset_config(), asset.interest_model(), now);

    let obligation = self.obligations.borrow_mut(obligation_id);
    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());


    let obligation_old_borrow_amount = obligation.debt(name).unsafe_debt_amount();


    let borrow_index = reserve.borrow_index().value();
    let residule = obligation.repay_debt<MarketType, CoinType>(coin.value(), borrow_index);
    obligation.enforce_post_borrow_repay_invariant<MarketType, CoinType>(min_borrow_amount);

    // interest updated, should be up to date
    let obligation_new_borrow_amount = if (obligation.has_debt(name)) obligation.debt(name).unsafe_debt_amount() else float::zero();

    let refund = coin.split(residule, ctx);

    let emode_group_id = obligation.emode_group();

    let emode_group = self.emode_group_registry.borrow_emode_group_mut(emode_group_id);
    let emode_group_total_borrow = emode_group.update_asset_borrow(name, obligation_old_borrow_amount, obligation_new_borrow_amount);

    let emode = emode_group.borrow_emode_mut(name);
    emode.borrow_mut_borrow_limiter().reduce_outflow(now, coin.value());


    reserve.repay_amount(coin);

    // try stop adl, if there is one on going
    let adl = dynamic_field::borrow_mut<ADLRegistryKey, AutoDeleverageRegistry>(&mut self.id, ADLRegistryKey {});

/// Checks if the obligation is safe from liquidation based on current obligation freshness. If the obligation data is not
/// latest, the result could be delayed. This could be acceptable in some cases, but for liquidation, called should refresh
/// obligation to latest state!
fun is_obligation_safe<MarketType>(
    emode_group: &EModeGroup,
    reserves: &GenericCoinTypeStorage<Reserve<MarketType>>,
    ema_spot_tolerance: &GenericCoinTypeStorage<Decimal>,

    obligation: &Obligation<MarketType>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
): bool {
    // make sure that their obligation still healthy, so users aren't borrowing over their collateral
    let borrow_weight_weighted_debt_value = debts_value_usd_non_liquidation(
        emode_group,
        reserves,
        ema_spot_tolerance,

        obligation,
        coin_decimals_registry,
        x_oracle,
        clock,
    );

    let (collateral_weighted_value, _) = collaterals_usd_non_liquidation(
        emode_group,
        reserves,
        ema_spot_tolerance,
        obligation,
        coin_decimals_registry,
        x_oracle,
        clock,
    );

    // NOTE: if collaterals_value == borrow_weight_weighted_debt_value, this is still safe, the boundary of safety
    collateral_weighted_value.ge(borrow_weight_weighted_debt_value)
}

// sum of every collateral usd value for borrow, returns both the total collateral usd value and the collateral factor weighted usd value (price x amount x collateralFactor)
fun collaterals_usd_non_liquidation<MarketType>(
    emode_group: &EModeGroup,
    reserves: &GenericCoinTypeStorage<Reserve<MarketType>>,
    ema_spot_tolerance: &GenericCoinTypeStorage<Decimal>,

    obligation: &Obligation<MarketType>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
): (Decimal, Decimal) {
    let mut total_weighted_usd = float::zero();
    let mut total_collateral_usd = float::zero();

    let mut deposit_types = obligation.deposit_types();

    let oracle_base_token = emode_group.get_oracle_base_token();

    while (!deposit_types.is_empty()) {
        let deposit_type = deposit_types.pop_back();

        let ctoken_amount = obligation.ctoken_amount_by_coin<MarketType>(deposit_type);
        let reserve = reserves.load_by_type<Reserve<MarketType>>(deposit_type);
        let collateral_amount = reserve.exchange_rate().mul(float::from(ctoken_amount));

        let collateral_config = emode_group.borrow_emode(deposit_type).collateral();

        // cannot be collateral, ignore
        if (!collateral_config.can_be_collateral()) { continue };
        let collateral_factor = collateral_config.collateral_factor();

        let tolerance = ema_spot_tolerance.load_by_type(deposit_type);
        let coin_price = get_price_with_check(x_oracle, deposit_type, oracle_base_token, clock, *tolerance);

        let decimals = coin_decimals_registry.decimals(deposit_type);

        let collateral_value_usd = coin_value(coin_price, collateral_amount, decimals);
        let collateral_weighted_usd = collateral_value_usd.mul(collateral_factor);

        total_collateral_usd = total_collateral_usd.add(collateral_value_usd);
        total_weighted_usd = total_weighted_usd.add(collateral_weighted_usd);
    };

    (total_weighted_usd, total_collateral_usd)
}

